SHEET_DATA["Данные взрослой матрицы"].formulas["J410"] = function(SHEET, cell, rangeVals) { return fn_CONCATENATE(cell(SHEET, "F410"), cell(SHEET, "I410"), cell(SHEET, "G410"), cell(SHEET, "I410"), cell(SHEET, "H410")); };
