function rangeVals(sheetName, startCoord, endCoord) {
  const start = parseCoord(startCoord);
  const end = parseCoord(endCoord);
  const rows = [];
  for (let r = start.row; r <= end.row; r++) {
    const rowVals = [];
    for (let c = start.col; c <= end.col; c++) {
      const colLetters = indexToCol(c);
      rowVals.push(cell(sheetName, colLetters + r));
    }
    rows.push(rowVals);
  }
  return rows;
}
function indexToCol(n) {
  let s = "";
  while (n > 0) {
    const rem = (n - 1) % 26;
    s = String.fromCharCode(65 + rem) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

function resetCaches() {
  for (const key of Object.keys(SHEET_DATA)) {
    SHEET_DATA[key].cache = {};
  }
}

function setInput(sheetName, coord, value) {
  SHEET_DATA[sheetName].literals[coord] = value;
  // clear any stale cached value at this coord (shouldn't have one, it's an input)
  delete SHEET_DATA[sheetName].cache[coord];
}

function cell(sheetName, coord) {
  const sheet = SHEET_DATA[sheetName];
  if (!sheet) throw new Error("Unknown sheet: " + sheetName);

  if (Object.prototype.hasOwnProperty.call(sheet.cache, coord)) {
    return sheet.cache[coord];
  }

  if (Object.prototype.hasOwnProperty.call(sheet.literals, coord)) {
    const v = sheet.literals[coord];
    sheet.cache[coord] = v;
    return v;
  }

  const formulaFn = sheet.formulas[coord];
  if (!formulaFn) {
    // Empty cell referenced -> Excel treats as 0 in arithmetic context.
    sheet.cache[coord] = 0;
    return 0;
  }

  // guard against runaway recursion (shouldn't be circular, but just in case)
  sheet.cache[coord] = undefined;
  const value = formulaFn(sheetName, cell, rangeVals);
  sheet.cache[coord] = value;
  return value;
}

function calculate(day, month, year, name) {
  resetCaches();
  const S = "Ввод данных";
  setInput(S, "D2", name || "");
  setInput(S, "AL2", Math.floor(day / 10));
  setInput(S, "AM2", day % 10);
  setInput(S, "AN2", Math.floor(month / 10));
  setInput(S, "AO2", month % 10);
  const y = String(year).padStart(4, "0");
  setInput(S, "AP2", Number(y[0]));
  setInput(S, "AQ2", Number(y[1]));
  setInput(S, "AR2", Number(y[2]));
  setInput(S, "AS2", Number(y[3]));
}

function getAll(sheetName) {
  const sheet = SHEET_DATA[sheetName];
  const coords = new Set([...Object.keys(sheet.literals), ...Object.keys(sheet.formulas)]);
  const result = {};
  for (const coord of coords) {
    try {
      result[coord] = cell(sheetName, coord);
    } catch (e) {
      result[coord] = "#ERR:" + e.message;
    }
  }
  return result;
}



